1	// The window both stores apply, so a list cannot cost more on one than on the other.
2	
3	import type {SessionCursor, SessionSummary} from '../../types/sessionStore.js';
4	
5	const DEFAULT_LIMIT = 50;
6	const MAX_LIMIT = 200;
7	
8	/** How many summaries one `listFor` may answer with: the caller's limit, bounded, and 50 when it names none. */
9	export function cappedLimit(limit: number | undefined): number {
10	  // A limit that is not a usable count reads as none given: handing a user an empty history for a typo is worse.
11	  if (limit === undefined || !Number.isFinite(limit) || limit < 0) return DEFAULT_LIMIT;
12	  // Floored rather than rejected, so only an explicit 0 answers nothing, and a fractional limit still works.
13	  return Math.min(Math.floor(limit), MAX_LIMIT);
14	}
15	
16	/** Newest activity first, with the larger session id ahead of the smaller on a tie, so the order is total. */
17	export function newestFirst(first: SessionSummary, second: SessionSummary): number {
18	  const gap = second.updatedAt.getTime() - first.updatedAt.getTime();
19	  if (gap !== 0) return gap;
20	  return first.sessionId < second.sessionId ? 1 : -1;
21	}
22	
23	/** The cursor's moment, from a `Date`, an ISO string or an epoch number, so a row that went through JSON still pages. */
24	export function cursorAt(cursor: SessionCursor): number {
