const isoTimes = (rows: SummaryRow[]): boolean => rows.every(row => isIso(row.createdAt) && isIso(row.updatedAt));

const listAnswerOf = (watch: Watch): {rows: SummaryRow[]} => {
  const answer = watch.seen.find(frame => frame.type === 'conversation_list');
  return {rows: answer?.conversations ?? []};
};

// The engine store per case: the real store holds the conversations, and `list` picks its list surface.
const sessionsHolding = (
  conversations: Array<[sessionId: string, owner: string, sentAt: string]>,
  list: 'real' | 'absent' | 'cannot' | 'rejects' = 'real'
): {store: SessionStore; listed: ListCall[]} => {
  const inner = new InMemorySessionStore();
  for (const [sessionId, owner, sentAt] of conversations) {
    const {entries} = inner.create(sessionId, owner);
    entries.push({role: 'user', content: `written in ${sessionId}`, timestamp: sentAt});
  }
  const listed: ListCall[] = [];
  const store: SessionStore = {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
    lookup: sessionId => inner.lookup(sessionId),
    ...(list === 'absent'
      ? {}
      : {
          listFor: async (userId: string | number, options?: SessionListOptions) => {
            listed.push({owner: userId, window: options});
            if (list === 'cannot') throw cannotListError();
            if (list === 'rejects') throw new Error('the replica set dropped the collection mid-scan: repl-xyz');
            return inner.listFor(userId, options);
          },
        }),
  };
  return {store, listed};
};

// A real engine on an ephemeral port, authenticated as the given user, with the history switch the issue adds.
const startEngine = async (options: {
  store: SessionStore;
  asUser: string;
  history?: HistorySwitch;
  orchestrator?: ChatOrchestrator;
}): Promise<string> => {
  const serverOptions: ServerOptions = {
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: options.asUser}),
    sessionStore: options.store,
    orchestrator: options.orchestrator ?? answeringOrchestrator,
    history: options.history,
  };
  const halServer = createServer(serverOptions);
  await halServer.start(0);
  engines.push(halServer);
  const {port} = halServer.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const open = (url: string): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  return client;
};

describe('a conversation list delivered over the websocket', () => {
  it('accepts list_conversations, drops a foreign field, and refuses a bad limit or a broken cursor, naming the field', () => {
    const refused: Array<{frame: Record<string, unknown>; field: string}> = [
      {frame: {type: 'list_conversations', limit: 0}, field: 'limit'},
      {frame: {type: 'list_conversations', limit: 201}, field: 'limit'},
      {frame: {type: 'list_conversations', limit: 1.5}, field: 'limit'},
      {frame: {type: 'list_conversations', limit: '10'}, field: 'limit'},
      {frame: {type: 'list_conversations', before: 'not a date'}, field: 'before'},
      {frame: {type: 'list_conversations', before: {updatedAt: '2026-01-01T00:00:00.000Z'}}, field: 'before'},
      {frame: {type: 'list_conversations', before: {sessionId: 'seed-winter'}}, field: 'before'},
    ];
    const windowed = {
      type: 'list_conversations',
      limit: 50,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'seed-winter'},
    };

    expect({
      plain: validateMessage({type: 'list_conversations'}),
      withForeignField: validateMessage({type: 'list_conversations', userId: 'u9', limit: 5}),
      windowed: validateMessage(windowed),
      requestsBefore: framesBeforeThisIssue
        .filter(frame => frame.type === 'user_message' || frame.type === 'ping')
        .map(frame => validateMessage(frame).valid),
      refusals: refused.map(({frame, field}) => [field, validateMessage(frame)]),
    }).toEqual({
      plain: {valid: true, data: {type: 'list_conversations', limit: undefined, before: undefined}},
      withForeignField: {valid: true, data: {type: 'list_conversations', limit: 5, before: undefined}},
      windowed: {valid: true, data: windowed},
      requestsBefore: [true, true],
      refusals: refused.map(({frame, field}) => [field, {valid: false, error: expect.stringContaining(field)}]),
    });
  });

  it("answers one conversation_list of the user's own conversations, newest first, with ISO times and no stream_end", async () => {
    const sessions = sessionsHolding([
      ['seed-summer', 'u1', '2025-06-01T09:00:00.000Z'],
      ['seed-winter', 'u1', '2025-01-01T09:00:00.000Z'],
      ['someone-else', 'u9', '2025-03-01T09:00:00.000Z'],
    ]);
    const url = await startEngine({store: sessions.store, asUser: 'u1', history: {enabled: true}});
    const watch = watched(open(url));
    await watch.once('connected');
    const connectedId = watch.seen[0].sessionId ?? '';

    await askForList(watch);

    const {rows} = listAnswerOf(watch);
    expect({
      frames: watch.seen.map(frame => frame.type),
      askedOf: sessions.listed.map(call => String(call.owner)),
      rows: rows.map(row => ({
        sessionId: row.sessionId,
        entryCount: row.entryCount,
        fields: Object.keys(row).sort(),
      })),
      timesAreIso: isoTimes(rows),
    }).toEqual({
      frames: ['connected', 'conversation_list'],
      askedOf: ['u1'],
      rows: [
        {sessionId: connectedId, entryCount: 0, fields: ['createdAt', 'entryCount', 'sessionId', 'updatedAt']},
        {sessionId: 'seed-summer', entryCount: 1, fields: ['createdAt', 'entryCount', 'sessionId', 'updatedAt']},
        {sessionId: 'seed-winter', entryCount: 1, fields: ['createdAt', 'entryCount', 'sessionId', 'updatedAt']},
      ],
      timesAreIso: true,
    });
  });

  it("lists the connecting user and hands the frame's window to the store as the frame sent it", async () => {
    const sessions = sessionsHolding([
      ['u1-march', 'u1', '2025-03-01T09:00:00.000Z'],
      ['u9-first', 'u9', '2025-02-01T09:00:00.000Z'],
      ['u9-second', 'u9', '2025-01-01T09:00:00.000Z'],
    ]);
    const url = await startEngine({store: sessions.store, asUser: 'u1', history: {enabled: true}});
    const watch = watched(open(url));
    await watch.once('connected');

    await askForList(watch, {
      type: 'list_conversations',
      limit: 2,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'u1-march'},
      userId: 'u9',
    });

    const {rows} = listAnswerOf(watch);
    expect({
      frames: watch.seen.map(frame => frame.type),
      asked: sessions.listed,
      rows: rows.map(row => row.sessionId),
    }).toEqual({
      frames: ['connected', 'conversation_list'],
      asked: [{owner: 'u1', window: {limit: 2, before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'u1-march'}}}],
      rows: ['u1-march'],
    });
  });

  it('answers an error, never an empty list, whenever the list cannot be given', async () => {
    const refusalFrom = async (store: SessionStore, history?: HistorySwitch) => {
      const url = await startEngine({store, asUser: 'u1', history});
      const watch = watched(open(url));
      await watch.once('connected');
      await askForList(watch);
      const answer = watch.seen.find(frame => frame.type === 'error');
      return {
        frames: watch.seen.map(frame => frame.type),
        code: answer?.code ?? '',
        hadList: watch.seen.some(frame => frame.type === 'conversation_list'),
      };
    };

    const switchedOff = await refusalFrom(sessionsHolding([['seed-summer', 'u1', '2025-06-01T09:00:00.000Z']]).store);
    const withoutListFor = await refusalFrom(sessionsHolding([], 'absent').store, {enabled: true});
    const cannotList = await refusalFrom(sessionsHolding([], 'cannot').store, {enabled: true});

    const rejecting = sessionsHolding([['seed-summer', 'u1', '2025-06-01T09:00:00.000Z']], 'rejects').store;
    const rejectUrl = await startEngine({store: rejecting, asUser: 'u1', history: {enabled: true}});
    const client = open(rejectUrl);
    const watch = watched(client);
    await watch.once('connected');
    const sessionId = watch.seen[0].sessionId ?? '';
    const errorLines: Array<Record<string, unknown>> = [];
    setLogger({...quiet, error: (category, message, fields) => void errorLines.push({category, message, ...fields})});
    try {
      await askForList(watch);
    } finally {
      setLogger(quiet);
    }
    const answer = watch.seen.find(frame => frame.type === 'error');

    expect({
      switchedOff,
      withoutListFor,
      cannotList,
      rejected: {
        frames: watch.seen.map(frame => frame.type),
        code: answer?.code ?? '',
        hadList: watch.seen.some(frame => frame.type === 'conversation_list'),
        storeDetail: (answer?.message ?? '').includes('collection'),
        socketOpen: client.readyState === WebSocket.OPEN,
        loggedSessionId: errorLines.some(line => line.sessionId === sessionId),
      },
    }).toEqual({
      switchedOff: {frames: ['connected', 'error'], code: 'UNSUPPORTED', hadList: false},
      withoutListFor: {frames: ['connected', 'error'], code: 'UNSUPPORTED', hadList: false},
      cannotList: {frames: ['connected', 'error'], code: 'UNSUPPORTED', hadList: false},
      rejected: {
        frames: ['connected', 'error'],
        code: 'SERVER_ERROR',
        hadList: false,
        storeDetail: false,
        socketOpen: true,
        loggedSessionId: true,
      },
    });
  });

  it("answers a history request beside a running turn, before that turn's stream_end", async () => {
    const gate = deferred();
    const held: ChatOrchestrator = {
      processMessage: async () => 'held',
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'held answer'};
        await gate.until;
        yield {type: 'stop', stopReason: 'end_turn'};
      },
    };
    const url = await startEngine({store: sessionsHolding([]).store, asUser: 'u1', history: {enabled: true}, orchestrator: held});
    const watch = watched(open(url));
    await watch.once('connected');

    const midStream = watch.once('entry_delta');
    watch.send({type: 'user_message', content: 'hello'});
    await midStream;
    const finished = watch.once('stream_end');
    await askForList(watch);
    gate.release();
    await finished;

    expect(watch.seen.map(frame => frame.type)).toEqual([
      'connected',
      'entry_upsert',
      'entry_upsert',
      'entry_delta',
      'conversation_list',
      'entry_commit',
      'stream_end',
    ]);
  });

  it('reopens a row of the list through the resume path that already exists', async () => {
    const sessions = sessionsHolding([['kept-alive', 'u1', '2025-09-01T09:00:00.000Z']]);
    const config: EngineConfig = {
      provider: {type: 'mock'},
      prompt: {identity: 'test'},
      auth: {ws: async () => ({id: 'u1'})},
      session: sessions.store,
      transport: {resume: {enabled: true}, history: {enabled: true}},
    };
    const engine = createHalEngine(config);
    await engine.start(0);
    engines.push(engine);
    const {port} = engine.server.address() as AddressInfo;
    const base = `ws://127.0.0.1:${port}/hal/ws`;

    const first = watched(open(base));
    await first.once('connected');
    const firstId = first.seen[0].sessionId ?? '';
    await askForList(first);
    const listed = listAnswerOf(first)
      .rows.map(row => row.sessionId ?? '')
      .filter(sessionId => sessionId !== firstId);
    first.close();

    const second = watched(open(`${base}?sessionId=${listed[0]}`));
    await second.once('connected');
    const reopened = second.seen[0];

    expect({
      listed,
      reopened: {
        sessionId: reopened.sessionId,
        resumed: reopened.resumed,
        replay: second.seen
          .filter(frame => frame.type === 'entry_upsert')
          .map(frame => [frame.index, frame.entry && 'content' in frame.entry ? frame.entry.content : '']),
      },
    }).toEqual({
      listed: ['kept-alive'],
      reopened: {sessionId: 'kept-alive', resumed: true, replay: [[0, 'written in kept-alive']]},
    });
  });
});

